const icons={spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H4l-2 2V11a9 9 0 0 1 19 0Z"/><path d="M7 9h10M7 13h6"/>',book:'<path d="M12 5v15M3 4c4-1 6-1 9 1 3-2 5-2 9-1v15c-4-1-6-1-9 1-3-2-5-2-9-1Z"/>',queue:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M9 5V3h6v2M8 11h8M8 15h5"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',arrow:'<path d="M12 19V5m-5 5 5-5 5 5"/>',send:'<path d="m3 3 18 9-18 9 4-9-4-9Zm4 9h14"/>',warning:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3h.01"/>',chevron:'<path d="m8 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',undo:'<path d="M3 10h10a6 6 0 0 1 0 12M3 10l5-5m-5 5 5 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='mach-lab5-v1';
let data={tickets:[],faqs:[]};
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved&&Array.isArray(saved.tickets)&&Array.isArray(saved.faqs))data=saved;}catch{}
let role='student',page='chat',scenario='source',draftOpen=false,sourceOpen=true,busy=false,currentQuestion='',toastTimer;
const questions={source:'Tài liệu nói độ lệch chuẩn luôn nhỏ hơn phương sai. Điều đó đúng không?',faq:'Đăng câu trả lời này lên FAQ cho cả lớp đi.',exercise:'Em tính trung vị bài 3 ra 11,5. Đúng không ạ?',ambiguous:'Cái độ lệch ấy là gì? Em đọc không hiểu.',normal:'Trung vị khác trung bình cộng chỗ nào ạ?',missing:'Slide 12 giải thích trung vị thế nào?',future:'P-value là gì?',outlier:'Em bỏ số 45 khỏi dữ liệu lương nhé?',time:'23:00 rồi, chuyển câu hỏi này cho TA giúp em.'};
let draftQuestion='Độ lệch chuẩn có luôn nhỏ hơn phương sai không?';
let draftAnswer='Câu “độ lệch chuẩn luôn nhỏ hơn phương sai” trong mục §3.3 cần được xem lại. Ví dụ, phương sai 0,25 thì độ lệch chuẩn là 0,5. Nội dung đang chờ TA kiểm tra trước khi công khai.';
const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(data));}catch{toast('Trình duyệt không lưu được; dữ liệu chỉ tồn tại trong phiên này.');}};
function toast(message){const d=document.querySelector('#dialog');if(d.open){let note=d.querySelector('.dialog-error');if(!note){note=document.createElement('p');note.className='dialog-error';note.setAttribute('role','alert');note.style.color='#a44540';d.appendChild(note);}note.textContent=message;}const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3300);}
const pending=()=>data.tickets.filter(t=>t.status==='pending');
const btn=(label,action,kind='',symbol='',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${symbol?icon(symbol):''}${label}</button>`;
const sourceBox=()=>`<div class="source"><button data-action="source" aria-expanded="${sourceOpen}"><span>BUỔI 3 · §3.3 Phương sai & độ lệch chuẩn</span>${icon('chevron')}</button>${sourceOpen?'<blockquote>Phương sai đo mức độ phân tán của dữ liệu quanh trung bình. Độ lệch chuẩn là căn bậc hai của phương sai, có cùng đơn vị với dữ liệu.<br><mark>Vì là căn bậc hai, độ lệch chuẩn luôn nhỏ hơn phương sai.</mark></blockquote>':''}</div>`;
function sidebar(){return `<aside class="sidebar"><div class="brand"><span class="brandmark">${icon('spark')}</span><div>mạch<small>HỌC HIỂU, ĐI XA.</small></div></div><div class="workspace"><span class="tile">${icon('book')}</span><div><strong>Không gian học tập</strong><small>Nhóm DKH · AI20K K5</small></div></div><div class="eyebrow">Không gian của bạn</div><nav class="nav">${navButtons()}</nav><div class="eyebrow">Lộ trình khóa học</div><div class="lessons"><div class="lesson"><i>✓</i>01 · Làm quen với dữ liệu</div><div class="lesson"><i>✓</i>02 · Khám phá dữ liệu</div><div class="lesson current"><i>03</i>Thống kê mô tả</div><div class="lesson"><i>04</i>Trực quan hóa · Chưa mở</div></div><div class="sidebar-bottom"><div class="night-card">${icon('moon')}<strong>Một chút mỗi tối.</strong><p>Không cần biết tất cả ngay.<br>Cứ bắt đầu từ một câu hỏi.</p></div><div class="profile"><span class="avatar">${role==='student'?'HV':'TA'}</span><div><strong>${role==='student'?'Học viên DKH':'Trợ giảng khóa học'}</strong><small>${role==='student'?'Nhập môn phân tích dữ liệu':'Không gian kiểm duyệt'}</small></div></div></div></aside>`;}
function navButtons(){return `<button data-action="nav" data-page="chat" class="${page==='chat'?'active':''}">${icon('chat')}Trợ lý học tập</button><button data-action="nav" data-page="faq" class="${page==='faq'?'active':''}">${icon('book')}FAQ của lớp <span class="count">${data.faqs.length}</span></button><button data-action="nav" data-page="queue" class="${page==='queue'?'active':''}">${icon('queue')}${role==='ta'?'Hàng chờ duyệt':'Yêu cầu của tôi'} <span class="count">${pending().length}</span></button>`;}
function render(){document.querySelector('#app').innerHTML=`<div class="shell">${sidebar()}<main class="main"><header class="topbar"><div class="breadcrumb">Khóa học <span style="padding:0 9px">/</span> <b>Nhập môn phân tích dữ liệu</b></div><div class="top-actions"><span class="demo-badge"><i class="dot"></i>PROTOTYPE</span><div class="role-switch" aria-label="Chọn vai trò demo"><button data-action="role" data-role="student" class="${role==='student'?'active':''}" aria-pressed="${role==='student'}">Học viên</button><button data-action="role" data-role="ta" class="${role==='ta'?'active':''}" aria-pressed="${role==='ta'}">Góc TA</button></div></div></header><div class="content"><nav class="mobile-logo">${navButtons()}</nav><div class="heading"><div><div class="eyebrow">${page==='chat'?'BUỔI 03 / THỐNG KÊ MÔ TẢ':page==='queue'?'KẾT NỐI VỚI NGƯỜI HƯỚNG DẪN':'KIẾN THỨC ĐƯỢC KIỂM CHỨNG'}</div><h1>${page==='chat'?'Học một chút. Khám phá thật nhiều!':page==='queue'?(role==='ta'?'Mỗi câu hỏi đều đáng được lắng nghe.':'Câu hỏi của bạn, luôn có nơi đến.'):'Học cùng nhau, hiểu cùng nhau.'}</h1><p class="subtitle">${page==='chat'?'Biến mỗi thắc mắc thành một bước tiến. Có Mạch đồng hành cùng bạn.':page==='queue'?'Theo dõi yêu cầu, kiểm tra bằng chứng và giữ mọi hành động minh bạch.':'Chỉ những nội dung đã được TA duyệt mới xuất hiện tại đây.'}</p></div><div class="date-label"><strong>23:00 · Thứ Năm</strong>12 tháng 11, 2026 · Giờ demo</div></div>${page==='chat'?`<div class="learning-modes"><button class="learning-mode" data-action="scenario" data-scenario="normal"><span class="mode-icon">${icon('spark')}</span><span><strong>Hiểu kiến thức</strong><small>Gỡ rối từng khái niệm</small></span>${icon('chevron')}</button><button class="learning-mode" data-action="scenario" data-scenario="exercise"><span class="mode-icon">${icon('book')}</span><span><strong>Luyện tập từng bước</strong><small>Tự khám phá cách làm</small></span>${icon('chevron')}</button><button class="learning-mode" data-action="scenario" data-scenario="faq"><span class="mode-icon">${icon('chat')}</span><span><strong>Học cùng cả lớp</strong><small>Góp một câu hỏi hay</small></span>${icon('chevron')}</button></div><div class="grid">${chat()}${rail()}</div>`:page==='queue'?queue():faq()}<footer class="footer"><span>DKH · LAB 05 &nbsp; / &nbsp; Dữ liệu dựng · Tương tác giả lập, không gửi đến TA thật.</span><button data-action="reset">Bắt đầu lại demo</button></footer></div></main></div>`;}
function rail(){return `<aside class="rail"><section class="panel"><div class="rail-head"><h3>Đang học cùng bạn</h3>${icon('book')}</div><div class="course-art" aria-hidden="true">${[24,40,33,54,43,62].map(h=>`<span style="height:${h}px"></span>`).join('')}</div><div class="eyebrow" style="font-size:9px">TÀI LIỆU BUỔI 03</div><h3 style="margin:4px 0 8px">Thống kê mô tả</h3>${[['3.1','Trung bình cộng'],['3.2','Trung vị'],['3.3','Phương sai & độ lệch chuẩn']].map(([n,t])=>`<div class="resource"><span class="resource-num">§${n}</span><div><p>${t}</p><small>${n==='3.3'?'Có nội dung cần xem lại':'Tài liệu khóa học'}</small></div></div>`).join('')}${btn('Mở tài liệu buổi 3','docs','soft','book')}<div class="deadline"><span>Bài tập 3 · Đang mở</span><b>13/11 · 23:59</b></div></section><section class="panel"><div class="rail-head"><h3>Có TA đồng hành</h3><span class="tag gray">Ngoài giờ trực</span></div><div class="ta-status"><span class="avatar">TA</span><div>Trợ giảng khóa học<br><small style="color:#859078">Giờ trực 08:00–22:00</small></div></div><p class="muted">Bạn vẫn có thể gửi câu hỏi. Ca trực tiếp theo bắt đầu lúc 08:00; thời gian trả lời chưa xác định.</p>${btn('Xem yêu cầu của tôi','my-requests','','queue')}</section><section class="panel quote"><p>“Hiểu vì sao,<br>trước khi biết đáp án.”</p><small>TRIẾT LÝ HỌC CÙNG MẠCH</small></section></aside>`;}
function chat(){return `<section class="panel"><div class="panel-head"><span class="ai-icon">${icon('spark')}</span><div><h3>Mạch · Trợ lý học tập AI</h3><p>Dựa trên tài liệu được cấp · Không làm bài thay bạn</p></div><span class="tag">${icon('shield')} Có nguồn dẫn</span></div><div class="chat-body"><div class="session-label">HÔM NAY · 23:00</div><div class="user-line"><div class="user-bubble">${esc(currentQuestion||questions[scenario]||'Em muốn hỏi bài.')}</div></div>${busy?'<div class="typing" role="status" aria-label="Đang tra cứu"><i></i><i></i><i></i></div>':`<div class="answer"><div class="answer-label">${icon('spark')} MẠCH <span style="font-weight:400;color:#a1aa97">· cùng bạn tìm hiểu</span></div>${answer()}</div>`}</div><div class="composer-area"><div class="suggestions" aria-label="Tình huống demo">${[['source','Tài liệu có câu sai'],['faq','Đề xuất FAQ'],['exercise','Kiểm tra bài 3'],['ambiguous','Chưa rõ khái niệm']].map(([s,label])=>`<button class="chip ${scenario===s?'selected':''}" data-action="scenario" data-scenario="${s}" ${busy?'disabled':''}>${label}</button>`).join('')}</div><form id="chat-form" class="composer"><textarea id="message" rows="1" maxlength="1000" placeholder="Điều gì đang làm bạn băn khoăn?" aria-label="Câu hỏi của bạn" ${busy?'disabled':''}></textarea><button class="send" aria-label="Gửi câu hỏi" ${busy?'disabled':''}>${icon('arrow')}</button></form><div class="composer-note">Câu trả lời có thể cần kiểm tra. Mạch không đưa hoặc xác nhận đáp số bài đang mở.</div></div></section>`;}
function answer(){if(scenario==='source')return `<div class="alert">${icon('warning')}<span><b>Nguồn có điểm cần xác minh</b><br>Đừng vội dùng kết luận này trước khi đối chiếu.</span></div><p>Bạn đã để ý một điểm rất quan trọng. Câu trong <b>mục §3.3</b> cần được xem lại về điều kiện toán học.</p>${sourceBox()}<div class="calculation"><span>Chẳng hạn:</span><b>√0,25 = 0,5</b><span>→ &nbsp;0,5 lớn hơn 0,25</span></div><p>Vì vậy, kết luận “luôn nhỏ hơn” không đúng trong mọi trường hợp. Mình không tự sửa giáo trình; bạn có thể gửi mục này để TA và giảng viên kiểm tra.</p><div class="actions">${btn('Gửi báo cáo cho TA','report','primary','send')}${btn('Tiếp tục học','continue','link','chevron')}</div><p style="font-size:9px;color:#8d967f">TA ngoài giờ trực · Ca tiếp theo từ 08:00 · Chưa xác định giờ trả lời</p>`;
if(scenario==='faq')return `<p>Mình có thể soạn bản nháp giúp bạn. <b>FAQ chỉ công khai sau khi TA hoặc giảng viên kiểm tra</b>, để kiến thức chưa xác minh không lan đến cả lớp.</p>${draftOpen?`<div class="draft"><span class="tag gray">Chưa công khai · Chỉ bạn thấy</span><div><label for="draft-question">Câu hỏi đề xuất</label><textarea id="draft-question" rows="2" maxlength="500">${esc(draftQuestion)}</textarea><label for="draft-answer">Câu trả lời dự kiến · TA sẽ kiểm tra</label><textarea id="draft-answer" rows="4" maxlength="2000">${esc(draftAnswer)}</textarea></div><div class="alert">${icon('warning')}<span>Liên quan §3.3: cần xác minh trước khi duyệt. Không đưa đáp số bài 3 đang mở vào FAQ.</span></div><div class="actions">${btn('Gửi TA duyệt FAQ','submit-faq','primary','send')}${btn('Hủy bản nháp','cancel-draft','danger','close')}</div></div>`:`<div class="state-card"><h3>Bản nháp đã đóng</h3><p>FAQ của lớp chưa thay đổi.</p>${btn('Soạn bản nháp mới','new-draft','soft','spark')}</div>`}`;
if(scenario==='exercise')return `<div class="alert">${icon('shield')}<span>Bài tập 3 đang mở · Hạn 13/11/2026 lúc 23:59</span></div><p>Mình không xác nhận hay bác đáp số bài đang mở. Nhưng mình có thể giúp bạn <b>tự kiểm tra cách làm</b>.</p><div class="source"><blockquote><b>§3.2 · Trung vị</b><br>Khi số giá trị là chẵn, trung vị là trung bình cộng của hai giá trị đứng giữa.</blockquote></div><p>Bạn đã sắp xếp các giá trị tăng dần chưa? Hãy thử xác định hai vị trí giữa trước nhé.</p><div class="actions">${btn('Xem tài liệu §3.2','median','soft','book')}${btn('Hỏi TA về cách làm','report','','send')}</div>`;
if(scenario==='ambiguous')return `<p>“Độ lệch” có thể đang chỉ nhiều ý khác nhau. Bạn đang muốn tìm hiểu phần nào?</p><div class="actions">${btn('Độ lệch chuẩn · §3.3','scenario','','book','data-scenario="source"')}${btn('Dữ liệu lệch · §3.2','skew','','book')}</div><p style="color:#8b957e;font-size:10px">Mình sẽ dựa vào lựa chọn của bạn để giải thích đúng phần đang vướng.</p>`;
if(scenario==='normal'||scenario==='skew')return `<p><b>Trung bình cộng</b> là tổng các giá trị chia cho số giá trị (§3.1). Nó bị kéo mạnh bởi ngoại lai.</p><p><b>Trung vị</b> là giá trị giữa khi dữ liệu đã được sắp xếp; với số lượng chẵn, lấy trung bình của hai giá trị giữa (§3.2). Trung vị ít bị ảnh hưởng bởi ngoại lai, nên thường dùng với dữ liệu lệch như thu nhập.</p><div class="actions">${btn('Xem tài liệu gốc','median','soft','book')}${btn('Tôi muốn hỏi cách khác','clarify','','chat')}</div>`;
if(scenario==='missing')return `<p>Tài liệu buổi 3 được cấp chỉ có <b>§3.1–§3.5</b>, không có slide đánh số. Mình không tìm thấy “slide 12”.</p>${btn('Xem §3.2 về trung vị','median','soft','book')}`;
if(scenario==='future')return `<p><b>P-value thuộc buổi 7: Kiểm định giả thuyết và p-value.</b> Hiện khóa học chỉ mở buổi 1–3, nên mình chưa có tài liệu để giải thích chi tiết nội dung này.</p>${btn('Chuyển câu hỏi cho TA','report','','send')}`;
if(scenario==='outlier')return `<p>Theo <b>§3.4</b>, trước khi bỏ một ngoại lai cần hỏi: đó là lỗi nhập liệu hay dữ liệu thật? Đề §3.5 chưa xác định số 45 là lỗi.</p><p>Bạn thử xem có bằng chứng nào cho thấy đây là lỗi nhập liệu không nhé. Mình không quyết định bỏ dữ liệu thay bạn.</p>`;
if(scenario==='time')return `<p>TA trực <b>08:00–22:00</b>, nên hiện đã ngoài giờ. Bạn có thể xác nhận gửi câu hỏi vào hàng chờ; mình chưa có căn cứ để hứa giờ trả lời chính xác.</p>${btn('Xem và xác nhận gửi','report','primary','send')}`;
return `<p>Mình chưa xác định được yêu cầu này trong các tình huống giả lập. Bạn có thể chọn một ca demo bên dưới hoặc gửi câu hỏi vào hàng chờ TA.</p>${btn('Gửi câu hỏi cho TA','report','','send')}`;}
function queue(){return `<div class="stats"><div class="stat"><b>${pending().length}</b>Đang chờ</div><div class="stat"><b>${data.tickets.filter(t=>t.status==='resolved'||t.status==='approved').length}</b>Đã xử lý</div><div class="stat"><b>${data.faqs.length}</b>FAQ công khai</div></div><div class="queue-grid wide-panel">${data.tickets.length?data.tickets.slice().reverse().map(ticketCard).join(''):`<div class="panel empty">${icon('queue')}<h2>Chưa có yêu cầu nào</h2><p>Gửi báo cáo tài liệu hoặc đề xuất FAQ từ khung chat để bắt đầu.</p>${btn('Mở trợ lý học tập','back-chat','primary','chat')}</div>`}</div>`;}
function ticketCard(t){const statuses={pending:'Đang chờ TA',cancelled:'Đã thu hồi',approved:'Đã duyệt & đăng FAQ',rejected:'TA đã từ chối',resolved:'TA đã phản hồi'};return `<article class="panel queue-card"><div class="queue-top"><h3>${t.type==='faq'?'Đề xuất FAQ':'Báo cáo / câu hỏi'} <span style="font-weight:400;color:#9aa58c">#${t.id.slice(-5)}</span></h3><span class="tag ${t.status==='pending'?'amber':t.status==='rejected'?'red':'gray'}">${statuses[t.status]||'Đang xử lý'}</span></div><div class="queue-meta">${esc(t.created)} · ${esc(t.source)} · Dữ liệu demo</div><p><b>${esc(t.question)}</b></p>${t.answer?`<p style="white-space:pre-wrap">${esc(t.answer)}</p>`:''}${t.note?`<p>Ghi chú: ${esc(t.note)}</p>`:''}${t.response?`<div class="state-card"><b>Phản hồi của TA</b><p>${esc(t.response)}</p></div>`:''}${t.status==='pending'?(role==='student'?`<small>Yêu cầu đã vào hàng chờ. Ca trực tiếp theo từ 08:00; chưa xác định giờ trả lời.</small><div class="actions">${btn(t.type==='faq'?'Thu hồi đề xuất':'Hoàn tác / Hủy phiếu','withdraw','danger','undo',`data-id="${t.id}"`)}</div>`:`<div class="alert">${icon('warning')}<span>Kiểm tra nguồn và tính đúng đắn; không đưa hoặc xác nhận đáp số bài 3 đang mở. Chế độ TA này chỉ để demo, không có phân quyền máy chủ.</span></div>${t.source.includes('3.3')?sourceBox():''}<div class="actions">${t.type==='faq'?btn('Kiểm tra / Sửa & duyệt','review','primary','check',`data-id="${t.id}"`):btn('Phản hồi học viên','reply','primary','chat',`data-id="${t.id}"`)}${btn('Từ chối kèm lý do','reject','danger','close',`data-id="${t.id}"`)}</div>`):''}</article>`;}
function faq(){return `<section class="panel wide-panel">${data.faqs.length?data.faqs.map(f=>`<article class="faq-item"><span class="tag">${icon('check')} Đã được TA duyệt</span><h2 style="margin-top:13px">${esc(f.question)}</h2><p>${esc(f.answer)}</p><small>Nguồn: ${esc(f.source)} · Duyệt trong phiên demo</small>${role==='ta'?`<div class="actions">${btn('Gỡ khỏi FAQ','remove-faq','danger','close',`data-id="${f.id}"`)}</div>`:''}</article>`).join(''):`<div class="empty">${icon('book')}<h2>Kiến thức tốt cần được kiểm tra.</h2><p>Chưa có FAQ được duyệt. Các bản nháp đang chờ không hiển thị tại đây.</p>${btn('Đề xuất một câu hỏi','scenario','primary','spark','data-scenario="faq"')}</div>`}</section>`;}
function modal(title,body,action,label,extra=''){const dialog=document.querySelector('#dialog');dialog.innerHTML=`<h2 id="dialog-title">${title}</h2>${body}<div class="actions">${btn('Quay lại','close-dialog')}${action?btn(label,action,'primary','',extra):''}</div>`;dialog.showModal();}
function closeModal(){document.querySelector('#dialog').close();}
function ticket(id){return data.tickets.find(t=>t.id===id);}
function newTicket(type,question,answer,note){const t={id:Date.now().toString(36)+Math.random().toString(36).slice(2,5),type,question,answer,note,source:type==='faq'||scenario==='source'?'Buổi 3 · §3.3':scenario==='exercise'?'Buổi 3 · §3.2 / §3.5':'Tài liệu khóa học',status:'pending',created:'23:00 (giờ demo)'};data.tickets.push(t);save();return t;}
function scenarioChange(s,q=''){if(busy)return;scenario=s;currentQuestion=q;draftOpen=s==='faq';page='chat';busy=true;render();setTimeout(()=>{busy=false;render();},380);}
document.addEventListener('input',e=>{if(e.target.id==='draft-question')draftQuestion=e.target.value;if(e.target.id==='draft-answer')draftAnswer=e.target.value;});
document.addEventListener('keydown',e=>{if(e.target.id==='message'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.closest('form').requestSubmit();}});
document.addEventListener('submit',e=>{if(e.target.id!=='chat-form')return;e.preventDefault();const q=document.querySelector('#message').value.trim();if(!q||busy)return;const n=q.toLocaleLowerCase('vi');let s=/faq|đăng/.test(n)?'faq':/slide/.test(n)?'missing':/p-value|buổi 7/.test(n)?'future':/45|ngoại lai/.test(n)?'outlier':/bài 3|11[,.]5|đáp số|giải hộ/.test(n)?'exercise':/ta|23:00|chuyển/.test(n)?'time':/phương sai|luôn nhỏ|0[,.]25/.test(n)?'source':/độ lệch/.test(n)?'ambiguous':/trung vị|trung bình/.test(n)?'normal':'unknown';scenarioChange(s,q);});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id,t=ticket(id);
switch(action){
case 'role':role=el.dataset.role;page=role==='ta'?'queue':'chat';render();break;
case 'nav':page=el.dataset.page;render();break;
case 'back-chat':page='chat';render();break;
case 'my-requests':page='queue';render();break;
case 'scenario':scenarioChange(el.dataset.scenario);break;
case 'source':sourceOpen=!sourceOpen;render();break;
case 'continue':scenarioChange('normal');break;
case 'skew':scenarioChange('skew','Em muốn hiểu dữ liệu lệch về một phía.');break;
case 'clarify':document.querySelector('#message').focus();toast('Bạn có thể diễn đạt lại câu hỏi trong ô chat.');break;
case 'new-draft':draftOpen=true;render();break;
case 'cancel-draft':modal('Hủy bản nháp FAQ?','<p>Bản nháp chưa được gửi cho TA và chưa công khai.</p>','confirm-cancel-draft','Hủy bản nháp');break;
case 'confirm-cancel-draft':draftOpen=false;closeModal();render();toast('Đã hủy bản nháp. FAQ không thay đổi.');break;
case 'report':modal('Xem trước khi gửi TA',`<p>Chỉ tạo phiếu sau khi bạn xác nhận.</p><label for="ticket-question">Câu hỏi</label><textarea id="ticket-question" class="field" rows="3" maxlength="1000">${esc(currentQuestion||questions[scenario]||'Câu hỏi về tài liệu')}</textarea><label for="ticket-note">Ghi chú thêm (không bắt buộc)</label><textarea id="ticket-note" class="field" rows="2" maxlength="1000"></textarea><div class="alert">${icon('clock')}<span>TA trực 08:00–22:00. Hiện ngoài giờ trực; chưa xác định thời gian trả lời. Đây là phiếu giả lập.</span></div>`,'confirm-report','Xác nhận gửi');break;
case 'confirm-report':{const q=document.querySelector('#ticket-question').value.trim();if(!q){toast('Vui lòng nhập câu hỏi.');return;}newTicket('report',q,scenario==='source'?'Câu tại §3.3 cần xem lại: phương sai 0,25 thì độ lệch chuẩn 0,5.':'',document.querySelector('#ticket-note').value.trim());closeModal();page='queue';render();toast('Đã tạo phiếu giả lập trong hàng chờ TA.');break;}
case 'submit-faq':if(!draftQuestion.trim()||!draftAnswer.trim()){toast('Cần có câu hỏi và nội dung bản nháp.');return;}modal('Gửi bản nháp cho TA duyệt?',`<p><b>${esc(draftQuestion)}</b></p><p>Bản nháp chưa công khai. TA cần kiểm tra nội dung và nguồn trước khi đăng.</p><div class="alert">${icon('clock')}<span>Giờ trực 08:00–22:00 · Chưa xác định giờ phản hồi.</span></div>`,'confirm-faq','Xác nhận gửi duyệt');break;
case 'confirm-faq':newTicket('faq',draftQuestion.trim(),draftAnswer.trim(),'');draftOpen=false;closeModal();page='queue';render();toast('Đã gửi duyệt giả lập. FAQ chưa được đăng.');break;
case 'withdraw':if(t?.status==='pending')modal('Thu hồi yêu cầu?', '<p>TA có thể đã đọc nội dung. Thu hồi sẽ dừng xử lý phiếu trong bản demo.</p>','confirm-withdraw','Thu hồi',`data-id="${id}"`);break;
case 'confirm-withdraw':if(t?.status==='pending'){t.status='cancelled';save();closeModal();render();toast('Đã thu hồi yêu cầu.');}break;
case 'review':if(role!=='ta'||t?.status!=='pending')return;modal('Kiểm tra & duyệt FAQ',`<p>Đọc nguồn và sửa nội dung trước khi công khai.</p><label for="review-question">Câu hỏi</label><textarea id="review-question" class="field" rows="2" maxlength="500">${esc(t.question)}</textarea><label for="review-answer">Câu trả lời đã kiểm tra</label><textarea id="review-answer" class="field" rows="5" maxlength="2000">${esc(t.answer)}</textarea><label class="check"><input type="checkbox" id="verified">Tôi đã kiểm tra tính đúng đắn, nguồn và không có đáp số bài đang mở.</label>`,'approve','Duyệt & đăng FAQ',`data-id="${id}"`);break;
case 'approve':{if(role!=='ta'||t?.status!=='pending')return;const q=document.querySelector('#review-question').value.trim(),a=document.querySelector('#review-answer').value.trim();if(!q||!a||!document.querySelector('#verified').checked){toast('Điền nội dung và xác nhận đã kiểm tra trước khi duyệt.');return;}t.status='approved';t.question=q;t.answer=a;data.faqs.push({id:t.id,question:q,answer:a,source:t.source});save();closeModal();render();toast('TA đã duyệt. FAQ hiện đã công khai trong demo.');break;}
case 'reply':case 'reject':if(role!=='ta'||t?.status!=='pending')return;modal(action==='reply'?'Phản hồi học viên':'Từ chối đề xuất',`<p>${esc(t.question)}</p><label for="ta-response">${action==='reply'?'Phản hồi của TA':'Lý do từ chối'}</label><textarea id="ta-response" class="field" rows="5" maxlength="2000" placeholder="Nhập nội dung cụ thể để học viên biết bước tiếp theo..."></textarea>`,'save-response',action==='reply'?'Gửi phản hồi':'Xác nhận từ chối',`data-id="${id}" data-status="${action==='reply'?'resolved':'rejected'}"`);break;
case 'save-response':{if(role!=='ta'||t?.status!=='pending')return;const response=document.querySelector('#ta-response').value.trim();if(!response){toast('Vui lòng nhập phản hồi hoặc lý do.');return;}t.response=response;t.status=el.dataset.status;save();closeModal();render();toast('Đã lưu phản hồi giả lập của TA.');break;}
case 'remove-faq':if(role==='ta')modal('Gỡ FAQ khỏi lớp?','<p>Nội dung đã được đọc không thể thu hồi. Việc gỡ chỉ ẩn FAQ khỏi danh sách trong demo.</p>','confirm-remove','Gỡ FAQ',`data-id="${id}"`);break;
case 'confirm-remove':if(role==='ta'){data.faqs=data.faqs.filter(f=>f.id!==id);if(t){t.status='resolved';t.response='FAQ đã được TA gỡ để xem xét lại.';}save();closeModal();render();toast('Đã gỡ FAQ.');}break;
case 'docs':case 'median':modal('Tài liệu buổi 3',`<p><b>§3.1 · Trung bình cộng</b><br>Tổng các giá trị chia cho số giá trị. Trung bình bị kéo mạnh bởi ngoại lai.</p><p><b>§3.2 · Trung vị</b><br>Giá trị đứng giữa khi sắp xếp dữ liệu tăng dần. Nếu số lượng chẵn, lấy trung bình cộng của hai giá trị giữa. Trung vị ít bị ảnh hưởng bởi ngoại lai.</p><p><b>§3.3 · Phương sai và độ lệch chuẩn</b><br>Phương sai đo mức phân tán quanh trung bình. Độ lệch chuẩn là căn bậc hai của phương sai, cùng đơn vị với dữ liệu.</p><div class="alert">${icon('warning')}<span>Câu trong nguồn “độ lệch chuẩn luôn nhỏ hơn phương sai” cần xem lại.</span></div><p><b>§3.4 · Giá trị ngoại lai</b><br>Trước khi bỏ ngoại lai, cần xem đó là lỗi nhập liệu hay dữ liệu thật.</p><p><b>§3.5 · Bài tập 3</b><br>Lương tháng (triệu đồng): 9, 10, 10, 11, 12, 12, 13, 45.<br>(a) Tính trung bình và trung vị. (b) Con số nào mô tả lương điển hình tốt hơn, vì sao?</p>`,null);break;
case 'reset':modal('Bắt đầu lại demo?','<p>Xóa các phiếu và FAQ giả lập đã tạo trong trình duyệt này.</p>','confirm-reset','Đặt lại demo');break;
case 'confirm-reset':data={tickets:[],faqs:[]};save();role='student';page='chat';scenario='source';currentQuestion='';draftOpen=false;closeModal();render();toast('Đã đặt lại demo.');break;
case 'close-dialog':closeModal();break;
}});
render();
